package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import org.apache.commons.compress.compressors.gzip.GzipCompressorOutputStream;
import org.apache.commons.compress.compressors.gzip.GzipParameters;
import org.junit.jupiter.api.Test;

final class GzipFileSystemProviderMutaGate8Test {
  @Test
  void headerFilename_isUsedOnlyWhenNonBlank_otherwiseHostFileName() throws IOException {
    Path named = Files.createTempFile("tarballfs-muta8-", ".gz");
    Path blank = Files.createTempFile("tarballfs-muta8-", ".gz");
    Path none = Files.createTempFile("tarballfs-muta8-", ".gz");
    try {
      byte[] payload = "payload".getBytes(StandardCharsets.UTF_8);
      writeGzip(named, "header-name.txt", payload);
      writeGzip(blank, "   ", payload);
      writeGzip(none, null, payload);

      // Non-blank header name is used as the virtual entry name, and the payload is readable.
      GzipFileSystemProvider p1 = new GzipFileSystemProvider();
      try (FileSystem fs = p1.newFileSystem(URI.create("gzip:" + named.toAbsolutePath()), Map.of())) {
        assertEquals(Set.of("header-name.txt"), listNames(fs));
        assertEquals("payload", Files.readString(fs.getPath("/", "header-name.txt")));
      }

      // Blank header name falls back to the host file name.
      GzipFileSystemProvider p2 = new GzipFileSystemProvider();
      try (FileSystem fs = p2.newFileSystem(URI.create("gzip:" + blank.toAbsolutePath()), Map.of())) {
        assertEquals(Set.of(blank.getFileName().toString()), listNames(fs));
        assertEquals("payload", Files.readString(fs.getPath("/", blank.getFileName().toString())));
      }

      // Missing header name falls back to the host file name.
      GzipFileSystemProvider p3 = new GzipFileSystemProvider();
      try (FileSystem fs = p3.newFileSystem(URI.create("gzip:" + none.toAbsolutePath()), Map.of())) {
        assertEquals(Set.of(none.getFileName().toString()), listNames(fs));
        assertEquals("payload", Files.readString(fs.getPath("/", none.getFileName().toString())));
      }
    } finally {
      Files.deleteIfExists(named);
      Files.deleteIfExists(blank);
      Files.deleteIfExists(none);
    }
  }

  private static Set<String> listNames(FileSystem fs) throws IOException {
    Set<String> names = new HashSet<>();
    try (DirectoryStream<Path> ds = Files.newDirectoryStream(fs.getPath("/"))) {
      for (Path p : ds) {
        names.add(p.getFileName().toString());
      }
    }
    return names;
  }

  private static void writeGzip(Path gzPath, String filename, byte[] payload) throws IOException {
    GzipParameters params = new GzipParameters();
    if (filename != null) {
      params.setFilename(filename);
    }
    try (OutputStream out = Files.newOutputStream(gzPath);
        GzipCompressorOutputStream gzOut = new GzipCompressorOutputStream(out, params)) {
      gzOut.write(payload);
    }
  }
}
